int main() {
  auto ok = [](string s) {
    for (int i = 1; i < (int)s.size(); ++i)
      if (s[i - 1] == s[i]) return false;
    return true;    
  };

  int t;
  cin >> t;
  while (t--) {
    int n, m;
    string s, t;
